head.script:
scwin.onpageload = function() {
    var jsonData = [{
        "col1": "a1",
        "col2": "a1"
    }, {
        "col1": "a2",
        "col2": "a2"
    }, {
        "col1": "a3",
        "col2": "a3"
    }, {
        "col1": "a4",
        "col2": "a4"
    }, {
        "col1": "a5",
        "col2": "a5"
    }, {
        "col1": "a6",
        "col2": "a6"
    }];
    dataList1.setJSON(jsonData);
};
scwin.onpageunload = function() {};
scwin.autoComplete1_onviewchange = function(info) {
    console.log("autoComplete gridViewItemset onviewchange");
    WebSquare.logger.printLog("autoComplete gridViewItemset onviewchange");
};
scwin.sel1_onviewchange = function(info) {
    console.log("select gridViewItemset onviewchange");
    WebSquare.logger.printLog("select gridViewItemset onviewchange");
};
scwin.checkLog = function(text) {
    var log = WebSquare.logger.getLog();
    return log.indexOf(text) > -1;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 autoComplete의 아이템리스트(역삼각형)를 클릭하고 'a2'값을 클릭하고 로그보기를 수행한다.
    //1. After running the sample, click the item list (inverted triangle) of autoComplete, click the value of 'a2' and execute the log view.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('autoComplete1_button').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('autoComplete1_gridViewItemTable_gridView_cell_1_0').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 1. onviewchange 이벤트가 발생하여 로그하단에 'autoComplete gridViewItemset onviewchange'값이 정상적으로 보여진다.(이전에는 onviewchange 이벤트 발생하지 않음)
    //1. The onViewchange event is generated and the value of 'autoComplete gridViewItemset onviewchange' is displayed normally at the bottom of the log (previously no onViewchange event)
    WebSquare.wUnit.addCommand("assert", "scwin.checkLog('autoComplete gridViewItemset onviewchange')", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //Test step 2. selectbox의 아이템리스트(역삼각형)를 클릭하고 'a2'값을 클릭하고 로그보기를 수행한다.
    //2. Click on the list of items in the selectbox (inverted triangle) and click on the value 'a2' to view the log.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('sel1_button').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('sel1_gridViewItemTable_gridView_cell_1_0').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 2.  onviewchange 이벤트가 발생하여 로그하단에 'select gridViewItemset onviewchange'값이 정상적으로 보여진다.
    //2. The onviewchange event occurs and the value of 'select gridViewItemset onviewchange' is displayed normally at the bottom of the log.
    WebSquare.wUnit.addCommand("assert", "scwin.checkLog('select gridViewItemset onviewchange')", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 03-Apr-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
